let editingIndex=null,drafts=[];const selectedQuestions=new Set();
function reflectBatch(){const dirty=library.dirty;$('#batch-status').textContent=dirty?'Unsaved batch · '+library.available.length+' sets':'All changes saved';$('#batch-save').disabled=!dirty;$('#batch-discard').disabled=!dirty;$('#selected-count').textContent=selectedQuestions.size+' selected';$('#delete-selected').disabled=!selectedQuestions.size;$('#select-all-questions').checked=!!custom.length&&selectedQuestions.size===custom.length;}
function refreshSetWorkspace(){custom=library.active?.questions||[];$('#edit-set-select').replaceChildren(...library.available.map(set=>{const option=document.createElement('option');option.value=set.id;option.textContent=(set.category||'Custom')+' · '+(set.title||'Untitled');return option;}));$('#edit-set-select').value=library.activeId||'';$('#set-title').value=library.active?.title||'';$('#set-category').value=library.active?.category||'';$('#delete-set').disabled=!library.active;reflectBatch();}
async function persistCustom(next){try{library.replaceQuestions(next);custom=library.active.questions;selectedQuestions.clear();renderCustom();return true;}catch(e){toast(e.message);return false;}}
async function saveBatch(force=false){try{if(!library.dirty&&!force)return true;const proposal=library.proposal(),approved=await confirmPack(proposal);if(!approved)return false;if(cloudBank.user)await cloudBank.save(approved);try{localStorage.setItem('chase-question-sets',JSON.stringify(approved));}catch(e){if(!cloudBank.user)throw e;toast('Batch saved to Firebase. This browser could not keep a local copy.');}library.commit(approved);custom=library.active?.questions||[];try{localStorage.setItem('sprint-custom',JSON.stringify(custom));}catch{}selectedQuestions.clear();renderCustom();syncQuestionSets();toast('Batch saved. All edits and deletions applied.');return true;}catch(e){toast('Batch not saved: '+e.message);return false;}}
function resetEditor(){editingIndex=null;$('#question-form').reset();$('#save-question').textContent='Add to batch +';$('#editor-title').textContent='Write a question';show('#cancel-edit',false);}
function editQuestion(index){editingIndex=index;const q=custom[index];$('#custom-prompt').value=q.prompt;['a','b','c'].forEach((k,i)=>$('#custom-'+k).value=q.options[i]);$('#custom-correct').value=q.correct;$('#custom-explanation').value=q.explanation||'';$('#save-question').textContent='Apply edit to batch';$('#editor-title').textContent='Edit question '+(index+1);show('#cancel-edit');$('#question-form').scrollIntoView({block:'center',behavior:'smooth'});$('#custom-prompt').focus();}
$('#cancel-edit').onclick=resetEditor;
const questionEditor=new QuestionEditor($('#custom-list'),{
 navigate(){renderCustom();},
 details(){$('#edit-set-select').focus();$('#set-workspace').scrollIntoView({block:'start',behavior:'smooth'});},
 error(error){toast(error.message);},
 update(index,patch){try{Object.assign(library.ensure().questions[index],patch);custom=library.active.questions;reflectBatch();}catch(e){toast(e.message);}},
 updateAnswer(index,answer,value){try{library.ensure().questions[index].options[answer]=value;custom=library.active.questions;reflectBatch();}catch(e){toast(e.message);}},
 select(index,on){on?selectedQuestions.add(index):selectedQuestions.delete(index);reflectBatch();},
 add(){try{const questions=library.ensure().questions;if(questions.length>=300)throw Error('A set can contain up to 300 questions.');questions.push({prompt:'',options:['','',''],correct:0,explanation:''});questionEditor.index=questions.length-1;renderCustom();}catch(e){toast(e.message);}},
 move(index,delta){const questions=library.ensure().questions,target=index+delta;if(target<0||target>=questions.length)return;[questions[index],questions[target]]=[questions[target],questions[index]];questionEditor.index=target;selectedQuestions.clear();renderCustom();},
 duplicate(index){try{const questions=library.ensure().questions;if(questions.length>=300)throw Error('A set can contain up to 300 questions.');questions.splice(index+1,0,structuredClone(questions[index]));questionEditor.index=index+1;selectedQuestions.clear();renderCustom();}catch(e){toast(e.message);}},
 remove(index){library.deleteQuestions([index]);selectedQuestions.clear();renderCustom();}
});
function renderCustom(){refreshSetWorkspace();$('#custom-count').textContent=custom.length;$('#select-all-questions').checked=!!custom.length&&selectedQuestions.size===custom.length;questionEditor.render(library.active,selectedQuestions);const included=!!library.active&&library.active.inBank!==false;const stored=library.draft.some(set=>set.id===library.activeId);$('#copy-starter').disabled=!library.active||(included&&stored);$('#use-custom').disabled=!library.active||!included;$('#set-membership').textContent=!library.active?'Select or create a set.':included?(stored?'Included in your user question bank.':'Starter resource · add to your saved bank to sync or publish.'): 'Not in your user question bank. Add it to make it available for races.';refreshPublishButton();}
$('#edit-set-select').onchange=()=>{library.select($('#edit-set-select').value);selectedQuestions.clear();resetEditor();renderCustom();};
for(const [id,key]of [['set-title','title'],['set-category','category']])$('#'+id).oninput=()=>{try{library.ensure()[key]=$('#'+id).value;custom=library.active.questions;reflectBatch();}catch(e){toast(e.message);}};
$('#new-set').onclick=()=>{try{library.create();selectedQuestions.clear();resetEditor();renderCustom();}catch(e){toast(e.message);}};
$('#delete-set').onclick=()=>{try{library.removeSet();selectedQuestions.clear();resetEditor();renderCustom();}catch(e){toast(e.message);}};
$('#select-all-questions').onchange=()=>{selectedQuestions.clear();if($('#select-all-questions').checked)custom.forEach((_,i)=>selectedQuestions.add(i));renderCustom();};
