$('#batch-save').onclick=()=>saveBatch();$('#batch-discard').onclick=()=>{library.discard();selectedQuestions.clear();resetEditor();renderCustom();toast('Unsaved batch discarded. Saved sets are unchanged.');};
$('#question-form').onsubmit=async e=>{e.preventDefault();const q={prompt:$('#custom-prompt').value.trim(),options:[$('#custom-a').value.trim(),$('#custom-b').value.trim(),$('#custom-c').value.trim()],correct:Number($('#custom-correct').value),explanation:$('#custom-explanation').value.trim()};if(!validQuestion(q)){toast('Enter a question, three different answers and one correct option.');return;}const next=[...custom];if(editingIndex===null)next.push(q);else next[editingIndex]=q;if(await persistCustom(next)){resetEditor();toast('Question added to the batch. Use Save all changes when ready.');}};
$('#export-pack').onclick=()=>{if(!library.active){toast('Create a set first.');return;}const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(library.active,null,2)],{type:'application/json'}));a.download=(library.active.title||'question-set').replace(/[^a-z0-9-]+/gi,'-')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};
