$('#import-pack').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>500000)throw Error('Set file is too large.');addImportedSet(parseSetImport(await f.text()));toast('Imported as a new set. Edit its category/title, then save the batch.');}catch(err){toast(err.message);}e.target.value='';};
$('#bank-editor-jump').onclick=()=>$('#custom-list').scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});
$('#import-pack-button').onclick=()=>$('#import-pack').click();
$('#copy-starter').onclick=()=>{try{library.setMembership(true);renderCustom();toast('Added to your bank in this batch. Save all changes when ready.');}catch(e){toast(e.message);}};
