function renderDrafts(){const host=$('#ai-drafts');host.replaceChildren(...drafts.map((q,index)=>{const card=document.createElement('fieldset');card.className='draft-card';const title=document.createElement('legend');title.textContent='Draft '+(index+1);card.append(title);function field(label,value,onchange,max){const wrap=document.createElement('label');wrap.textContent=label;const el=document.createElement('input');el.value=value;el.maxLength=max;el.oninput=()=>onchange(el.value);wrap.append(el);return wrap;}card.append(field('Question',q.prompt,v=>q.prompt=v,150));const answers=document.createElement('div');answers.className='custom-options';q.options.forEach((v,i)=>answers.append(field(['A','B','C'][i],v,v=>q.options[i]=v,55)));card.append(answers);const why=document.createElement('label');why.textContent='Simple explanation (optional)';const whyInput=document.createElement('input');whyInput.maxLength=400;whyInput.value=q.explanation||'';whyInput.oninput=()=>{q.explanation=whyInput.value;};why.append(whyInput);card.append(why);const label=document.createElement('label');label.textContent='Correct answer';const select=document.createElement('select');['A','B','C'].forEach((v,i)=>{const o=document.createElement('option');o.value=i;o.textContent=v;select.append(o);});select.value=q.correct;select.onchange=()=>q.correct=Number(select.value);label.append(select);const remove=document.createElement('button');remove.className='text-button';remove.textContent='Discard draft';remove.onclick=()=>{drafts.splice(index,1);renderDrafts();};card.append(label,remove);return card;}));show('#ai-accept',drafts.length>0);}
$('#ai-import').onclick=()=>{try{const imported=parseSetImport($('#ai-response').value);drafts=imported.questions;$('#ai-set-category').value=imported.category||'Year '+$('#ai-year').value;$('#ai-set-title').value=imported.title||$('#ai-topic').value||'New question set';show('#ai-set-metadata');renderDrafts();$('#ai-status').textContent=`${drafts.length} draft questions for a NEW set. Customise the category and title, review the answers, then create it.`;}catch(e){$('#ai-status').textContent=e.message;}};
$('#ai-accept').onclick=()=>{try{if(!drafts.length||!drafts.every(validQuestion))throw Error('Check all draft questions and answers.');const title=$('#ai-set-title').value.trim(),category=$('#ai-set-category').value.trim();if(!title||!category)throw Error('Enter a title and Year / category for the new set.');addImportedSet({title,category,questions:drafts});drafts=[];renderDrafts();show('#ai-set-metadata',false);$('#ai-response').value='';$('#ai-status').textContent='New set created in the batch. Existing sets are unchanged. Save all changes when ready.';}catch(e){$('#ai-status').textContent=e.message;}};
async function createPair(){clearInterval(pairTimer);phoneConnection?.close();cameraReady=false;$('#camera-race-button').disabled=true;$('#pair-qr').textContent='Creating a secure camera link…';$('#pair-pin-code').textContent='— — — — — —';$('#camera-status').textContent='Connecting the two devices…';$('#calibrate-button').textContent='Create new link';try{const pc=phoneConnection=new RTCPeerConnection(rtcConfig),channel=pc.createDataChannel('motion',{ordered:false,maxRetransmits:0});phoneChannel=channel;channel.onmessage=e=>{try{const state=JSON.parse(e.data);phoneLostAt=performance.now();if(input!=='phone')return;lastCameraState=state;handleMotion(state);updateDeviceStatus();if(cameraReady){$('#camera-race-button').disabled=false;$('#camera-race-button').textContent=pairOnly?'Done':'Start race →';$('#camera-status').textContent='Phone connected and calibrated. Start the race when everyone is ready.';}else $('#camera-status').textContent=`Phone connected · ${state.detected||0}/${settings?.players||Number($('#players-select').value)} players visible. Calibrate on the phone.`;}catch{}};channel.onopen=()=>{syncPhonePlayers();attachPhonePreview($('#phone-pair'));updateDeviceStatus();$('#camera-status').textContent='Phone connected. Enable its camera and calibrate the players.';};channel.onclose=()=>{if(phoneConnection!==pc)return;cameraReady=false;lastCameraState=null;$('#paired-camera-video').srcObject=null;updateDeviceStatus();$('#camera-race-button').disabled=true;if(race){pausedForTracking=true;pause('Reconnect your phone.','Use Re-lock / reconnect camera below to pair again without leaving this race.');}};pc.addTransceiver('video',{direction:'recvonly'});pc.ontrack=e=>{$('#paired-camera-video').srcObject=e.streams[0]||new MediaStream([e.track]);};const offer=await gather(pc),id=crypto.randomUUID();if(phoneConnection!==pc||$('#camera-screen').hidden)return;const response=await pairRequest('/api/pair',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,offer,players:settings?.players||Number($('#players-select').value)})});const pairing=await response.json();if(!response.ok)throw Error(pairing.error||'Could not create the pairing link. Try again.');if(phoneConnection!==pc||$('#camera-screen').hidden){await pairRequest('/api/pair',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});return;}$('#pair-pin-code').textContent=pairing.pin.slice(0,3)+' '+pairing.pin.slice(3);$('#pair-pin-expiry').textContent='Valid for 5 minutes · one camera device';const link=new URL('./index.html',import.meta.url);link.hash='camera='+id;$('#pair-link').href=link;const qr=window.qrcode?.(0,'M');if(qr){qr.addData(link.href);qr.make();$('#pair-qr').innerHTML=qr.createSvgTag({scalable:true,margin:2});}else $('#pair-qr').textContent='Open the camera controller link below on your phone.';$('#camera-status').textContent=location.hostname==='localhost'||location.hostname==='127.0.0.1'?'Local preview: use the hosted HTTPS link for a phone camera. Laptop camera works here.':'Scan the QR code. On your phone, open the link and enable its camera.';let polls=0;pairTimer=setInterval(async()=>{try{if(++polls>200){clearInterval(pairTimer);$('#camera-status').textContent='Pairing link timed out. Create a new one.';return;}const res=await pairRequest('/api/pair?id='+id,{cache:'no-store'});if(!res.ok)return;const data=await res.json();if(data.answer&&!pc.remoteDescription){await pc.setRemoteDescription(data.answer);clearInterval(pairTimer);await pairRequest('/api/pair',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});}}catch{}},1500);}catch(e){$('#pair-qr').textContent='';$('#camera-status').textContent=e.message;}}
async function startPhone(id){qrScanner.stop();music.suspend('phone');show('#home',false);show('#splash',false);show('#nav',false);show('#selection-screen',false);show('#phone-controller');show('#load-status',false);try{const res=await pairRequest('/api/pair?id='+id,{cache:'no-store'});if(!res.ok)throw Error('This pairing link expired. Create a new QR code on the game screen.');const data=await res.json(),pc=new RTCPeerConnection(rtcConfig);phoneConnection=pc;let dataChannel=null;pc.ondatachannel=e=>{dataChannel=e.channel;dataChannel.onmessage=async event=>{try{const command=JSON.parse(event.data);if(command.type==='players'&&Number.isInteger(command.count)&&command.count>=1&&command.count<=4){data.players=command.count;await camera?.setCount(command.count);}if(command.type==='relock'&&camera){if(command.count)await camera.setCount(command.count);camera.calibrate();}}catch{}};dataChannel.onopen=()=>{$('#phone-status').textContent='Connected! Enable the camera to begin.';$('#phone-enable').disabled=false;requestWakeLock();};dataChannel.onclose=()=>{$('#phone-status').textContent='Game disconnected. Create a new link on the game screen.';camera?.stop();};};await pc.setRemoteDescription(data.offer);for(const transceiver of pc.getTransceivers())if(transceiver.receiver.track.kind==='video')transceiver.direction='sendonly';await pc.setLocalDescription(await pc.createAnswer());if(pc.iceGatheringState!=='complete')await new Promise(resolve=>{const timer=setTimeout(resolve,4500);pc.onicegatheringstatechange=()=>{if(pc.iceGatheringState==='complete'){clearTimeout(timer);resolve();}};});const answered=await pairRequest('/api/pair',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,answer:pc.localDescription})});if(!answered.ok)throw Error((await answered.json()).error);$('#phone-status').textContent='Connecting to the game screen…';setTimeout(()=>{if(pc.connectionState!=='connected')$('#phone-status').textContent='Still connecting. Put both devices on the same Wi-Fi and create a new link if needed.';},15000);
$('#phone-enable').onclick=async()=>{$('#phone-enable').disabled=true;try{camera?.stop();camera=new CameraController({video:$('#phone-video'),canvas:$('#phone-overlay'),zones:$('#phone-zones'),count:data.players,onStatus:s=>$('#phone-status').textContent=s,onState:state=>{if(dataChannel?.readyState==='open')dataChannel.send(JSON.stringify(state));}});await camera.start();const sender=pc.getTransceivers().find(t=>t.receiver.track.kind==='video')?.sender;if(sender)await sender.replaceTrack(camera.stream.getVideoTracks()[0]);$('#phone-calibrate').disabled=false;$('#phone-enable').textContent='Camera enabled';}catch(e){$('#phone-status').textContent=cameraError(e);$('#phone-enable').disabled=false;}};$('#phone-calibrate').onclick=()=>{if(camera.calibrate())$('#phone-status').textContent='Ready! Start the race on the game screen. Keep this phone still.';};}catch(e){$('#phone-status').textContent=e.message;}}

