function syncQuestionSets(selected='all'){const year=$('#year-select').value,categories=catalog();$('#year-select').replaceChildren(...categories.map(category=>{const option=document.createElement('option');option.value=category.id;option.textContent=category.label;return option;}));$('#year-select').value=categories.some(c=>c.id===year)?year:categories[0]?.id||'';const category=categories.find(c=>c.id===$('#year-select').value);$('#question-set-select').replaceChildren(...(category?.sets||[]).map(set=>{const option=document.createElement('option');option.value=set.id;option.textContent=set.title+' · '+set.questions.length;return option;}));$('#question-set-select').value=selected;if(!$('#question-set-select').value)$('#question-set-select').selectedIndex=0;}
