function stopSelectionCamera(){if(camera?.selection){camera.stop();camera=null;cameraReady=false;}$('#selection-camera-lock').disabled=true;$('#selection-camera-enable').disabled=false;$('#selection-camera-enable').textContent='Enable camera';$('#selection-camera-status').textContent='Stand freely with your whole body visible. Tap a person to lock them.';show('#selection-camera-empty');}
