function updateDeviceStatus(){const phone=phoneChannel?.readyState==='open',local=!!camera?.running,tracked=lastCameraState?.detected||0;const message=phone?`Phone camera connected · ${tracked} players visible${lastCameraState?.calibrated?' · locked':''}`:local?`Laptop camera connected · ${tracked} players visible`:'No camera device connected. Pair a phone or enable your laptop camera.';for(const id of ['connected-device-status','pair-device-status','paired-camera-status'])$('#'+id).textContent=message;}
