const community=new PublicBank();let ownPublications=new Map(),publicationLoading=false,publicationEpoch=0,communityRows=[],communityScope='all',previewResource=null;
function refreshPublishButton(){const set=library.active,published=!!set&&ownPublications.has(set.id);$('#publish-set').textContent=published?'Publish changes':'Publish to public';$('#publish-set').disabled=!set||publicationLoading;$('#publish-status').textContent=publicationLoading?'Checking your published sets…':published?'This set is public. Save your edits, then publish changes to update its public copy.':'This set stays private until you choose to publish it.';}
async function refreshOwnPublications(){const epoch=++publicationEpoch;ownPublications=new Map();if(!cloudBank.user){publicationLoading=false;refreshPublishButton();return;}publicationLoading=true;refreshPublishButton();try{const records=await community.owned();if(epoch!==publicationEpoch)return;ownPublications=new Map(records.map(record=>[record.sourceId,record.key]));}catch(e){if(epoch===publicationEpoch)$('#publish-status').textContent='Could not check publication status: '+e.message;}finally{if(epoch===publicationEpoch){publicationLoading=false;refreshPublishButton();}}}
