async function renderPublicBank(){const status=$('#public-bank-status');status.textContent='Loading resources…';communityRows=starterSets(PACKS).map(set=>({key:set.id,kind:'starter',set}));try{const rows=await community.list();communityRows.push(...rows.map(row=>({...row,kind:'community'})));}catch(e){toast('Community could not load: '+e.message+' Starter packs are available.');}const selected=$('#community-category').value;$('#community-category').replaceChildren(...['',...new Set(communityRows.map(row=>row.set.category))].map(category=>{const option=document.createElement('option');option.value=category;option.textContent=category||'All categories';return option;}));$('#community-category').value=selected;filterCommunity();}
