$('#publish-set').onclick=async()=>{try{if(!$('#publish-consent').checked)throw Error('Tick the public sharing checkbox first.');if(library.dirty)throw Error('Save your batch before publishing.');const set=library.saved.find(s=>s.id===library.activeId);if(!set){library.ensure();renderCustom();throw Error('Starter added to your draft bank. Save all changes, then publish it.');}if(set.deleted)throw Error('Select an available set before publishing.');const result=await community.publish(set,library.saved.findIndex(s=>s.id===set.id));ownPublications.set(set.id,result.key);$('#publish-consent').checked=false;refreshPublishButton();toast('Public copy published. Your changes are now available to the community.');}catch(e){toast(e.message);}};

const saveGate=new SaveConfirmation();let resolveSave=null;
function confirmPack(next){if(resolveSave)return Promise.resolve(false);saveGate.begin(next);renderSaveConfirmation();show('#save-confirm-screen');$('#save-confirm-next').focus();return new Promise(resolve=>resolveSave=resolve);}
function cancelSave(){saveGate.cancel();show('#save-confirm-screen',false);const resolve=resolveSave;resolveSave=null;resolve?.(false);}
function renderSaveConfirmation(){const level=saveGate.level;$('#save-confirm-screen').dataset.level=level;$('#save-confirm-level').textContent=`BATCH CONFIRMATION ${level} OF 3`;$('#save-confirm-title').textContent=['Review the whole batch.','Apply all edits and deletions?','Final batch confirmation.'][level-1];$('#save-confirm-copy').textContent=['All pending changes will be saved together. Nothing is applied to the saved sets yet.','This replaces the saved library with the reviewed sets below, including question and set deletions.','The next click commits the complete batch. Cancel keeps the saved library unchanged and leaves the draft available.'][level-1];$('#save-confirm-next').textContent=level===3?'Save the complete batch':level===2?'I understand — final check':'Reviewed — continue';const next=saveGate.proposal,host=$('#save-confirm-summary');host.replaceChildren();const count=document.createElement('strong');count.textContent=`${library.saved.length} saved sets → ${next.length} proposed sets · ${next.reduce((n,set)=>n+set.questions.length,0)} questions`;host.append(count);const removed=library.saved.filter(old=>!next.some(set=>set.id===old.id));for(const set of removed){const row=document.createElement('p');row.textContent='Delete set: '+set.category+' · '+set.title;host.append(row);}for(const set of next){const old=library.saved.find(s=>s.id===set.id);if(JSON.stringify(old)===JSON.stringify(set))continue;const row=document.createElement('p');row.textContent=(set.deleted?'Delete starter pack: ':set.inBank===false?'Remove from user bank: ':old?'Update: ':'Save set: ')+set.category+' · '+set.title+' · '+set.questions.length+' questions';host.append(row);for(const q of set.questions.slice(0,4)){const line=document.createElement('small');line.textContent=q.prompt+' · ✓ '+q.options[q.correct];host.append(line,document.createElement('br'));}}}
$('#save-confirm-cancel').onclick=cancelSave;
$('#save-confirm-next').onclick=()=>{const committed=saveGate.advance();if(committed){show('#save-confirm-screen',false);const resolve=resolveSave;resolveSave=null;resolve?.(committed);}else renderSaveConfirmation();};
