try{const cameraId=new URLSearchParams(location.hash.slice(1)).get('camera');if(cameraId){await loadingSequence(()=>startPhone(cameraId),value=>setLoading(Math.round(value),'Preparing the camera connection…'));show('#loading-screen',false);}else{stadium=new Stadium($('#stadium'));await loadingSequence(()=>stadium.loadCharacters(),value=>setLoading(Math.round(value),value>=100?'Ready to race!':'Loading your stadium…'));setLoading(100,'Ready to race!');show('#loading-screen',false);show('#splash');show('#load-status',false);$('#splash-start').disabled=false;$('#splash-start').textContent='Press to Start →';if(location.hash==='#join'){show('#splash',false);show('#home');show('#nav');show('#join-screen');$('#join-pin').focus();}let last=performance.now();function frame(now){const dt=Math.min(.06,(now-last)/1000);last=now;if(document.hidden||!$('#phone-controller').hidden){requestAnimationFrame(frame);return;}if(race){const prev=race.phase;race.tick(dt);const impacts=impactKeys(race).filter(key=>!playedImpacts.has(key));impacts.forEach(key=>playedImpacts.add(key));if(impacts.length&&!muted){try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();playOof(audio);}catch{}}if(race.phase==='feedback'&&prev!=='feedback'&&!muted){try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const good=race.players.some(p=>p.hurdleJump&&p.jumpLane===race.question.correct),bad=race.players.some(p=>!p.caught&&(!p.hurdleJump||p.jumpLane!==race.question.correct));if(good)playCrowd(audio,true);if(bad)playCrowd(audio,false,good?.65:0);}catch{}}if(race.finished&&prev!=='results')finishRace();if(input==='phone'&&phoneLostAt&&now-phoneLostAt>2500&&!race.paused&&!race.finished){pausedForTracking=true;pause('Waiting for your phone.','The camera signal stopped. Keep the phone browser open, or reconnect below.');}if(now-lastUI>30){updateUI();lastUI=now;}}if(race)stadium.update(dt,race);requestAnimationFrame(frame);}requestAnimationFrame(frame);}}catch(e){$('#load-status').textContent='The stadium could not load. Check your connection, then refresh.';$('#loading-text').textContent='The game could not finish loading. Check your connection and try again.';show('#loading-retry');console.error(e);}
